#!/bin/bash
# One-line health check of the pY1 chain and the things that ran out before.
cd /d/factorio-explore/py-tutorial/tools/agent
node a.js eval code="local o={} local function st(e) for k,v in pairs(defines.entity_status) do if v==e.status then return k end end return '?' end for _,q in pairs({{'vrauks-paddock-mk01',133.5,-62.5,'pad'},{'slaughterhouse-mk01',134.5,-38.5,'sla'},{'glassworks-mk01',0.5,-15.5,'flask'},{'research-center-mk01',55,-15,'rc'},{'assembling-machine-1',20.5,18.5,'red'}}) do local e=s.find_entity(q[1],{q[2],q[3]}) o[#o+1]=q[4]..':'..st(e):sub(1,12)..'/'..e.products_finished end local t={} for _,n in pairs({'copper-plate','wood','raw-coal','coke','titanium-plate','automation-science-pack','py-science-pack-1','fawogae-substrate'}) do local c=storage.char.get_item_count(n) for _,e in pairs(s.find_entities_filtered{type='container',force='player'}) do if not storage.input_chests[e.unit_number] then c=c+e.get_inventory(defines.inventory.chest).get_item_count(n) end end t[#t+1]=n:sub(1,8)..'='..c end local ws=0 for _,p in pairs({{{-26,-9},{-8,-1}},{{29,-1},{56,13}}}) do for _,e in pairs(s.find_entities_filtered{area=p,type='container'}) do ws=ws+e.get_inventory(defines.inventory.chest).count_empty_stacks() end end return table.concat(o,' ')..' | '..table.concat(t,' ')..' | wh_free='..ws..' | '..tostring(f.current_research and f.current_research.name)..' '..math.floor(f.research_progress*100)..'%'" 2>&1 | grep -oE '"value":"[^"]*"' | sed 's/"value":"//; s/"$//'
node quota.js | sed 's/;.*//'
